 	 * options.
 	 */

 	if (!remount || fsi->opts & BIT(Opt_mode)) {
 		tmp_mode = READ_ONCE(inode->i_mode) & ~S_IALLUGO;
 		tmp_mode |= fsi->mode;
 		WRITE_ONCE(inode->i_mode, tmp_mode);
 	}

 	if (!remount || fsi->opts & BIT(Opt_uid))
 		inode->i_uid = fsi->uid;

 	if (!remount || fsi->opts & BIT(Opt_gid))
 		inode->i_gid = fsi->gid;

 	if (remount && (fsi->opts & BIT(Opt_uid) || fsi->opts & BIT(Opt_gid))) {

 		update_uid = fsi->opts & BIT(Opt_uid);
 		update_gid = fsi->opts & BIT(Opt_gid);

+		srcu_idx = eventfs_remount_lock();
 		rcu_read_lock();
 		list_for_each_entry_rcu(ti, &tracefs_inodes, list) {
 			if (update_uid) {
 				ti->flags &= ~TRACEFS_UID_PERM_SET;
 				ti->vfs_inode.i_uid = fsi->uid;
 			}

 			if (update_gid) {
 				ti->flags &= ~TRACEFS_GID_PERM_SET;
 				ti->vfs_inode.i_gid = fsi->gid;
 			}

 			/*
 			 * Note, the above ti->vfs_inode updates are
 			 * used in eventfs_remount() so they must come
 			 * before calling it.
 			 */
 			if (ti->flags & TRACEFS_EVENT_INODE)
 				eventfs_remount(ti, update_uid, update_gid);
 		}
 		rcu_read_unlock();
+		eventfs_remount_unlock(srcu_idx);
 	}

 	return 0;
 }


 static int tracefs_drop_inode(struct inode *inode)
 {
 	struct tracefs_inode *ti = get_tracefs(inode);

 	/*
 	 * This inode is being freed and cannot be used for
 	 * eventfs. Clear the flag so that it doesn't call into
 	 * eventfs during the remount flag updates. The eventfs_inode
-	 * gets freed after an RCU cycle, so the content will still
+	 * gets freed after an SRCU cycle, so the content will still
 	 * be safe if the iteration is going on now.
 	 */
 	ti->flags &= ~TRACEFS_EVENT_INODE;

 	return 1;
 }



